const AIOverlay: React.FC<AIOverlayProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  durationInSeconds = 12,
  overlayTitle = "Malloy Studio's response",
  tags = ["System Design", "Code"],
  questionTitle = "Question",
  questionTime = "2:30",
  questionText = "Could you tell me more about your previous work experience?",
  answerTitle = "Answer",
  answerTime = "2:30",
  answerText = "Sure. I've been working as a Project Manager for about three years, mostly in digital product teams. I've managed cross-functional teams including designers, developers, and QA. My focus has been on delivering projects on time while keeping scope and budget under control.\n\nIn my last role, I led several web and SaaS projects from kickoff to launch. I was responsible for planning, setting timelines, aligning stakeholders, and making sure the team had clear priorities. One of the key results was reducing delivery delays by improving sprint planning and risk management.",
  glassOpacity = 0.1,
  blurAmount = 12,
}) => {
  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  const bgColorResolved = transparentBackground ? "transparent" : backgroundColor;
  const panelWidth = Math.min(width * 0.65, 1200);

  // Core Entrance Animations
  const panelScale = interpolate(
    spring({
      frame,
      fps,
      config: { damping: 20, mass: 1 },
    }),
    [0, 1],
    [0.95, 1]
  );
  const panelOpacity = interpolate(frame, [0, 15], [0, 1], { extrapolateRight: "clamp" });

  const questionOpacity = interpolate(frame, [10, 20], [0, 1], { extrapolateRight: "clamp" });
  const questionY = interpolate(frame, [10, 20], [10, 0], { extrapolateRight: "clamp" });

  const answerStartOpacity = interpolate(frame, [20, 30], [0, 1], { extrapolateRight: "clamp" });
  const answerStartY = interpolate(frame, [20, 30], [10, 0], { extrapolateRight: "clamp" });

  const inputOpacity = interpolate(frame, [30, 40], [0, 1], { extrapolateRight: "clamp" });
  const inputY = interpolate(frame, [30, 40], [10, 0], { extrapolateRight: "clamp" });

  // Typing Logic
  const startTypingFrame = 30;
  const idealSpeed = 40; // chars per second
  const idealFrames = (answerText.length / idealSpeed) * fps;
  const maxFrames = (durationInSeconds * fps) * 0.6; // Max 60% of video duration for typing
  const typingFrames = Math.min(idealFrames, maxFrames);
  const endTypingFrame = startTypingFrame + typingFrames;

  const charsToShow = Math.floor(
    interpolate(frame, [startTypingFrame, endTypingFrame], [0, answerText.length], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    })
  );

  const displayedText = answerText.slice(0, charsToShow);
  const cursorOpacity = Math.floor(frame / 15) % 2 === 0 ? 1 : 0;
  const showCursor = charsToShow < answerText.length;

  const regenerateOpacity = interpolate(frame, [endTypingFrame + 10, endTypingFrame + 30], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColorResolved, fontFamily: interFamily, alignItems: "center", justifyContent: "center" }}>
      
      {/* Background Orbs to show off the glass effect if not transparent */}
      {!transparentBackground && (
        <AbsoluteFill style={{ opacity: 0.8 }}>
          <div style={{ position: "absolute", inset: 0, display: "flex" }}>
            <div style={{ flex: 1, background: "linear-gradient(135deg, rgba(255,255,255,0.05) 0%, rgba(0,0,0,0.2) 100%)" }} />
            <div style={{ flex: 1, background: "linear-gradient(135deg, rgba(0,0,0,0.1) 0%, rgba(255,255,255,0.1) 100%)" }} />
          </div>
          <div style={{ position: "absolute", top: "-10%", left: "-10%", width: "60%", height: "60%", background: "radial-gradient(circle, rgba(100,50,250,0.4) 0%, rgba(0,0,0,0) 70%)", filter: "blur(120px)" }} />
          <div style={{ position: "absolute", bottom: "-10%", right: "-10%", width: "70%", height: "70%", background: "radial-gradient(circle, rgba(50,200,200,0.3) 0%, rgba(0,0,0,0) 70%)", filter: "blur(120px)" }} />
        </AbsoluteFill>
      )}

      {/* Main Glass Panel */}
      <div
        style={{
          width: panelWidth,
          backgroundColor: `rgba(255, 255, 255, ${glassOpacity})`,
          backdropFilter: `blur(${blurAmount}px)`,
          WebkitBackdropFilter: `blur(${blurAmount}px)`,
          border: "1px solid rgba(255, 255, 255, 0.2)",
          borderRadius: 24,
          padding: "32px 40px",
          color: "white",
          display: "flex",
          flexDirection: "column",
          boxShadow: "0 30px 60px rgba(0,0,0,0.2)",
          transform: `scale(${panelScale})`,
          opacity: panelOpacity,
        }}
      >
        {/* Header */}
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "32px" }}>
          <div style={{ display: "flex", alignItems: "center", gap: "12px" }}>
            <div style={{ opacity: 0.8 }}>
              <DocIcon />
            </div>
            <span style={{ fontSize: 18, fontWeight: 500, letterSpacing: "-0.02em" }}>{overlayTitle}</span>
          </div>
          <div style={{ display: "flex", gap: "12px", alignItems: "center" }}>
            <div style={{ opacity: 0.6, display: "flex", alignItems: "center", marginRight: "4px" }}>
              <ClockIcon />
            </div>
            {tags.map((tag) => (
              <div key={tag} style={{ border: "1px solid rgba(255,255,255,0.3)", borderRadius: 16, padding: "4px 14px", fontSize: 13, fontWeight: 500, letterSpacing: "0.02em" }}>
                {tag}
              </div>
            ))}
          </div>
        </div>

        {/* Content Body */}
        <div style={{ display: "flex", flexDirection: "column", gap: "32px" }}>
          
          {/* Question Block */}
          <div style={{ opacity: questionOpacity, transform: `translateY(${questionY}px)`, display: "flex", flexDirection: "column", gap: "12px" }}>
            <div style={{ display: "flex", gap: "12px", alignItems: "baseline" }}>
              <span style={{ fontWeight: 600, fontSize: 16 }}>{questionTitle}</span>
              <span style={{ opacity: 0.5, fontSize: 14 }}>{questionTime}</span>
            </div>
            <div style={{ fontSize: 20, lineHeight: 1.5, opacity: 0.9, letterSpacing: "-0.01em" }}>
              {questionText}
            </div>
          </div>

          {/* Answer Block */}
          <div style={{ opacity: answerStartOpacity, transform: `translateY(${answerStartY}px)`, display: "flex", flexDirection: "column", gap: "12px" }}>
            <div style={{ display: "flex", gap: "12px", alignItems: "baseline" }}>
              <span style={{ fontWeight: 600, fontSize: 16 }}>{answerTitle}</span>
              <span style={{ opacity: 0.5, fontSize: 14 }}>{answerTime}</span>
            </div>
            
            {/* The Text Container: invisible full text maintains size, visible text sits on top to prevent layout shift */}
            <div style={{ fontSize: 20, lineHeight: 1.6, position: "relative", whiteSpace: "pre-wrap", letterSpacing: "-0.01em" }}>
              <div style={{ opacity: 0 }}>{answerText}</div>
              <div style={{ position: "absolute", top: 0, left: 0, width: "100%", height: "100%" }}>
                {displayedText}
                <span
                  style={{
                    opacity: cursorOpacity,
                    display: showCursor ? "inline-block" : "none",
                    width: 2,
                    height: 20,
                    backgroundColor: "white",
                    marginLeft: 4,
                    verticalAlign: "middle",
                    transform: "translateY(-2px)",
                  }}
                />
              </div>
            </div>

            {/* Footer Buttons */}
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: "16px", opacity: regenerateOpacity }}>
              <div style={{ display: "flex", alignItems: "center", gap: "8px", border: "1px solid rgba(255,255,255,0.2)", borderRadius: 20, padding: "8px 16px", backgroundColor: "rgba(255,255,255,0.05)" }}>
                <SparkleIcon />
                <span style={{ fontSize: 14, fontWeight: 500 }}>Regenerate Response</span>
              </div>
              <div style={{ padding: "8px", opacity: 0.6 }}>
                <CopyIcon />
              </div>
            </div>
          </div>
        </div>

        {/* Bottom Input Field */}
        <div style={{ opacity: inputOpacity, transform: `translateY(${inputY}px)`, marginTop: "40px", display: "flex", alignItems: "center", border: "1px solid rgba(255,255,255,0.2)", borderRadius: 32, padding: "10px 10px 10px 24px", backgroundColor: "rgba(255,255,255,0.05)", justifyContent: "space-between" }}>
          <span style={{ opacity: 0.5, fontSize: 16 }}>Ask a question... [/]</span>
          <div style={{ display: "flex", gap: "16px", alignItems: "center" }}>
            <div style={{ opacity: 0.6 }}>
              <CameraIcon />
            </div>
            <div style={{ display: "flex", alignItems: "center", gap: "8px", backgroundColor: "rgba(255,255,255,0.15)", padding: "10px 20px", borderRadius: 24 }}>
              <span style={{ fontSize: 15, fontWeight: 500 }}>Send</span>
              <SendIcon />
            </div>
          </div>
        </div>

      </div>
    </AbsoluteFill>
  );
};

export default AIOverlay;